### Iteration 2: Shared Memory Optimization
Now I'll optimize the kernel by using shared memory to reduce global memory accesses. Each thread block will load a tile of matrix A and B into shared memory to reuse data.

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Define shared memory tiles
    extern __shared__ float shared_mem[];
    float* tileA = shared_mem;
    float* tileB = &tileA[blockDim.y * blockDim.x];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    for (int tile = 0; tile < gridDim.x; tile++) {
        // Load tile of A into shared memory
        int load_row = row;
        int load_col = tile * blockDim.x + threadIdx.x;
        if (load_row < N && load_col < N) {
            tileA[threadIdx.y * blockDim.x + threadIdx.x] = A[load_row * N + load_col];
        } else {
            tileA[threadIdx.y * blockDim.x + threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        int load_row_b = tile * blockDim.y + threadIdx.y;
        int load_col_b = col;
        if (load_row_b < N && load_col_b < N) {
            tileB[threadIdx.y * blockDim.x + threadIdx.x] = B[load_row_b * N + load_col_b];
        } else {
            tileB[threadIdx.y * blockDim.x + threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product
        for (int k = 0; k < blockDim.x; k++) {
            sum += tileA[threadIdx.y * blockDim.x + k] * tileB[k * blockDim.x + threadIdx.x];
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 threadsPerBlock(16, 16);
    dim3 numBlocks((N + threadsPerBlock.x - 1) / threadsPerBlock.x, 
                   (N + threadsPerBlock.y - 1) / threadsPerBlock.y);

    // Calculate shared memory size (2 tiles of 16x16 floats)
    size_t sharedMemSize = 2 * threadsPerBlock.x * threadsPerBlock.y * sizeof(float);

    matmul_kernel<<<numBlocks, threadsPerBlock, sharedMemSize>>>(A.data_ptr<float>(), 
                                                                 B.data_ptr<float>(), 
                                                                 C.data_ptr<float>(), 
                                                                 N);
    return C;
}
"""

cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

# The load_inline function returns a module with the function as an attribute
matmul_module = load_inline(
    name='matmul_module',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['matmul_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        return matmul_module.matmul_cuda(A, B)
```

