### Iteration 3: Optimized Shared Memory Access
I'll optimize the shared memory access pattern to avoid bank conflicts by:
1. Using 2D shared memory arrays
2. Transposing tile B during loading
3. Using coalesced memory access patterns

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 16

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Declare 2D shared memory tiles
    __shared__ float tileA[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float tileB[BLOCK_SIZE][BLOCK_SIZE];

    int row = blockIdx.y * BLOCK_SIZE + threadIdx.y;
    int col = blockIdx.x * BLOCK_SIZE + threadIdx.x;

    float sum = 0.0f;

    for (int tile_idx = 0; tile_idx < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; tile_idx++) {
        // Load tile of A into shared memory (coalesced access)
        int load_row_A = row;
        int load_col_A = tile_idx * BLOCK_SIZE + threadIdx.x;
        if (load_row_A < N && load_col_A < N) {
            tileA[threadIdx.y][threadIdx.x] = A[load_row_A * N + load_col_A];
        } else {
            tileA[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory with transposition (coalesced access)
        int load_row_B = tile_idx * BLOCK_SIZE + threadIdx.y;
        int load_col_B = col;
        if (load_row_B < N && load_col_B < N) {
            tileB[threadIdx.x][threadIdx.y] = B[load_row_B * N + load_col_B]; // Transpose during load
        } else {
            tileB[threadIdx.x][threadIdx.y] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product (no bank conflicts)
        for (int k = 0; k < BLOCK_SIZE; k++) {
            sum += tileA[threadIdx.y][k] * tileB[threadIdx.x][k];
        }

        __syncthreads();
    }

    // Write result to global memory (coalesced access)
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 threadsPerBlock(BLOCK_SIZE, BLOCK_SIZE);
    dim3 numBlocks((N + BLOCK_SIZE - 1) / BLOCK_SIZE, 
                   (N + BLOCK_SIZE - 1) / BLOCK_SIZE);

    matmul_kernel<<<numBlocks, threadsPerBlock>>>(A.data_ptr<float>(), 
                                                 B.data_ptr<float>(), 
                                                 C.data_ptr<float>(), 
                                                 N);
    return C;
}
"""

cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

# The load_inline function returns a module with the function as an attribute
matmul_module = load_inline(
    name='matmul_module',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['matmul_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        return matmul_module.matmul_cuda(A, B)
