### Iteration 4: Register Blocking Optimization
I'll implement register blocking (also known as loop unrolling) to increase arithmetic intensity and reduce memory accesses. Each thread will compute a 4x4 block of the output matrix.

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 16
#define REG_TILE_SIZE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Declare 2D shared memory tiles
    __shared__ float tileA[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float tileB[BLOCK_SIZE][BLOCK_SIZE];

    // Thread coordinates within block
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block coordinates
    int blockRow = blockIdx.y * BLOCK_SIZE;
    int blockCol = blockIdx.x * BLOCK_SIZE;

    // Each thread computes a 4x4 block of the output
    float c[REG_TILE_SIZE][REG_TILE_SIZE] = {{0.0f}};

    // Loop over tiles
    for (int tile_idx = 0; tile_idx < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; tile_idx++) {
        // Load tile of A into shared memory (coalesced access)
        int load_row_A = blockRow + ty;
        int load_col_A = tile_idx * BLOCK_SIZE + tx;
        if (load_row_A < N && load_col_A < N) {
            tileA[ty][tx] = A[load_row_A * N + load_col_A];
        } else {
            tileA[ty][tx] = 0.0f;
        }

        // Load tile of B into shared memory (coalesced access)
        int load_row_B = tile_idx * BLOCK_SIZE + ty;
        int load_col_B = blockCol + tx;
        if (load_row_B < N && load_col_B < N) {
            tileB[ty][tx] = B[load_row_B * N + load_col_B];
        } else {
            tileB[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot products using register blocking
        for (int k = 0; k < BLOCK_SIZE; k++) {
            // Prefetch values into registers
            float a_val = tileA[ty][k];
            float b_val = tileB[k][tx];

            // Unroll the inner loops
            c[0][0] += a_val * b_val;
            c[0][1] += a_val * tileB[k][tx + 1];
            c[0][2] += a_val * tileB[k][tx + 2];
            c[0][3] += a_val * tileB[k][tx + 3];

            c[1][0] += tileA[ty + 1][k] * b_val;
            c[1][1] += tileA[ty + 1][k] * tileB[k][tx + 1];
            c[1][2] += tileA[ty + 1][k] * tileB[k][tx + 2];
            c[1][3] += tileA[ty + 1][k] * tileB[k][tx + 3];

            c[2][0] += tileA[ty + 2][k] * b_val;
            c[2][1] += tileA[ty + 2][k] * tileB[k][tx + 1];
            c[2][2] += tileA[ty + 2][k] * tileB[k][tx + 2];
            c[2][3] += tileA[ty + 2][k] * tileB[k][tx + 3];

            c[3][0] += tileA[ty + 3][k] * b_val;
            c[3][1] += tileA[ty + 3][k] * tileB[k][tx + 1];
            c[3][2] += tileA[ty + 3][k] * tileB[k][tx + 2];
            c[3][3] += tileA[ty + 3][k] * tileB[k][tx + 3];
        }

        __syncthreads();
    }

    // Write 4x4 block to global memory (coalesced access)
    int row = blockRow + ty * REG_TILE_SIZE;
    int col = blockCol + tx * REG_TILE_SIZE;

    for (int i = 0; i < REG_TILE_SIZE; i++) {
        for (int j = 0; j < REG_TILE_SIZE; j++) {
            if (row + i < N && col + j < N) {
                C[(row + i) * N + (col + j)] = c[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    // Each block handles a 16x16 tile, each thread handles a 4x4 tile
    dim3 threadsPerBlock(BLOCK_SIZE / REG_TILE_SIZE, BLOCK_SIZE / REG_TILE_SIZE);
    dim3 numBlocks((N + BLOCK_SIZE - 1) / BLOCK_SIZE, 
                   (N + BLOCK_SIZE - 1) / BLOCK_SIZE);

    matmul_kernel<<<numBlocks, threadsPerBlock>>>(A.data_ptr<float>(), 
                                                 B.data_ptr<float>(), 
                                                 C.data_ptr<float>(), 
                                                 N);
    return C;
}
"""

cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

# The load_inline function returns a module with the function as an attribute
matmul_module = load_inline(
    name='matmul_module',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['matmul_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        return matmul_module.matmul_cuda(A, B)
